schema:
{
  "description": "Registra la fattura nel gestionale: compila i campi e scegli per ognuno il metodo con cui lo otterresti in Content Understanding.",
  "baseAnalyzerId": "prebuilt-document",
  "config": {
    "estimateFieldSourceAndConfidence": true
  },
  "fieldSchema": {
    "fields": {
      "DataFattura": {
        "type": "date",
        "method": "extract",
        "description": "Data della fattura."
      },
      "CondizioniPagamento": {
        "type": "string",
        "method": "extract",
        "description": "Condizioni di pagamento, per esempio \"60 gg d.f.\"."
      },
      "Fornitore": {
        "type": "string",
        "method": "extract",
        "description": "Ragione sociale del fornitore."
      },
      "IvaTotale": {
        "type": "number",
        "method": "extract",
        "description": "L'IVA totale è stampata nel documento: si estrae, non si ricalcola."
      },
      "Totale": {
        "type": "number",
        "method": "extract",
        "description": "Il \"Totale documento\"."
      }
    }
  }
}
